mapper.update:
UPDATE invoice_applications SET status = #{status},
  next_check_at = TIMESTAMPADD(MICROSECOND, #{delayMs,jdbcType=INTEGER} * 1000, UTC_TIMESTAMP(6))
WHERE order_id = #{orderId}

UPDATE invoice_applications SET status = 'REVIEW_REQUIRED', review_reason = #{reason},
  review_detail = LEFT(#{detail}, 1024), next_check_at = NULL
WHERE order_id = #{orderId}

UPDATE invoice_applications a SET a.next_check_at = UTC_TIMESTAMP(6)
WHERE a.next_check_at IS NOT NULL AND EXISTS (
  SELECT 1 FROM invoice_attempts t WHERE t.order_id = a.order_id AND t.request_id = #{requestId}
    AND t.status = 'PENDING'
)
